begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,competitor_id uuid,report_id uuid,recommendation_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision handoff rollback fixture'from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision other handoff rollback fixture'from fixture;
insert into public.competitors(id,property_id,name,is_active)select competitor_id,property_id,'Saved brief competitor',true from fixture;
insert into public.competitor_units(competitor_id,unit_type,bedrooms,rent_min)select competitor_id,'One bedroom',1,1200 from fixture;
insert into public.property_units(org_id,property_id,unit_type,canonical_key,bedrooms,rent_min,active,review_status,expires_at)select '22222222-2222-2222-2222-222222222222'::uuid,f.property_id,n,n,1,1800,true,case when n='pending'then 'pending'else 'approved'end,case when n='expired'then statement_timestamp()-interval '1 day'else null end from fixture f cross join unnest(array['approved','pending','expired'])n;
create function pg_temp.result_for(report_id uuid,rec uuid)returns jsonb language sql as $$select jsonb_build_object('schemaVersion','market-brief-v2','reportId',r.id,'propertyId',r.property_id,'sourceHash',r.source_hash,'snapshotAt',r.source_snapshot->>'snapshotAt','analysis','{}'::jsonb,'recommendations',jsonb_build_array(jsonb_build_object('id',rec,'title','Review exact sources','kind','comparison_review','priority','review','rationale','Dates are unknown','evidence','[]'::jsonb,'subjectIds','[]'::jsonb,'limitations','[]'::jsonb)))from public.marketvision_briefs r where r.id=report_id;$$;

create function pg_temp.fail_handoff_approval()returns trigger language plpgsql as $$begin if current_setting('p11.fixture.fail_approval',true)='yes'then raise exception 'Injected approval receipt failure';end if;return new;end$$;
create trigger fixture_handoff_approval_failure before insert on public.shared_approvals for each row execute function pg_temp.fail_handoff_approval();
do $$declare f fixture;r jsonb;b public.marketvision_briefs;h public.marketvision_handoffs;payload jsonb;decision jsonb;review_id uuid:=gen_random_uuid();handoff_id uuid:=gen_random_uuid();decision_id uuid:=gen_random_uuid();next_id uuid;old_role text;old_rent numeric;begin select * into f from fixture;
 perform pg_temp.check(not has_table_privilege('authenticated','public.marketvision_handoffs','select')and not has_function_privilege('authenticated','public.prepare_marketvision_handoff(uuid,uuid,uuid,jsonb)','execute'),'private handoff intent cannot be forged by browser clients');
 perform public.begin_marketvision_brief(f.report_id,f.property_id,f.actor_id,'{"windowDays":30,"reason":"Exact handoff report snapshot"}');
 select * into b from public.marketvision_briefs where id=f.report_id;
 perform public.complete_marketvision_brief(f.report_id,f.property_id,f.actor_id,b.source_hash,pg_temp.result_for(f.report_id,f.recommendation_id));
 payload:=jsonb_build_object('briefId',f.report_id,'expectedVersion',2,'recommendationId',f.recommendation_id,'expectedReviewId',review_id,'title','Reviewed draft title','objective','Invite operators to review approved property differentiators','channel','facebook','format','image','reason','Prepare exact reviewed marketing draft');
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.property_id,gen_random_uuid(),payload)->>'state'='forbidden','request requires current actor access');
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.other_property,f.actor_id,payload)->>'state'='not_found','preparation cannot cross properties');
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload)->>'state'='stale_review','unreviewed recommendations cannot become a handoff');
 perform public.review_marketvision_brief(review_id,f.property_id,f.actor_id,jsonb_build_object('briefId',f.report_id,'expectedVersion',2,'recommendationId',f.recommendation_id,'expectedReviewId',null,'decision','consider','acknowledgedSourceChange',false,'reason','Consider exact saved comparison'));
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload||'{"format":"text","channel":"instagram"}')->>'state'='invalid_format','unsupported channel format does not create a handoff');
 begin perform public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload||'{"sourceFacts":[{"text":"forged"}]}');raise exception 'MISSING forged payload rejection';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm like 'Review the saved draft%','caller cannot supply source evidence');end;
 update public.competitor_units set rent_min=2000 where competitor_id=f.competitor_id;
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload)->>'state'='source_changed','changed source stops preparation');
 update public.competitor_units set rent_min=1200 where competitor_id=f.competitor_id;
 -- Updated-at stamps are part of provenance: make a new current report instead of rewriting history.
 f.report_id:=gen_random_uuid();update fixture set report_id=f.report_id;
 perform public.begin_marketvision_brief(f.report_id,f.property_id,f.actor_id,'{"windowDays":30,"reason":"Current handoff report after source edit"}');select * into b from public.marketvision_briefs where id=f.report_id;
 perform public.complete_marketvision_brief(f.report_id,f.property_id,f.actor_id,b.source_hash,pg_temp.result_for(f.report_id,f.recommendation_id));review_id:=gen_random_uuid();
 perform public.review_marketvision_brief(review_id,f.property_id,f.actor_id,jsonb_build_object('briefId',f.report_id,'expectedVersion',2,'recommendationId',f.recommendation_id,'expectedReviewId',null,'decision','consider','acknowledgedSourceChange',false,'reason','Consider the current saved comparison'));payload:=payload||jsonb_build_object('briefId',f.report_id,'expectedReviewId',review_id);
 r:=public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload);perform pg_temp.check(r->>'state'='saved'and r->>'draftCreated'='false','preparation saves one exact intent without creating a draft');select * into h from public.marketvision_handoffs where id=handoff_id;
 perform pg_temp.check((select count(*)=0 from public.social_content_briefs where property_id=f.property_id),'preparation has no downstream side effect');
 perform pg_temp.check(h.draft->'sourceFacts'->0->>'text'='Dates are unknown'and h.draft->'sourceFacts'->0->>'source'like 'marketvision_proposal:%'and h.draft->'connectionIds'='[]'and h.draft->'assetIds'='[]','draft uses retained advisory recommendation and no unapproved destinations/assets');
 perform pg_temp.check((select context_payload->'draft'=h.draft and context_payload->>'reportHash'=(select result_hash from public.marketvision_briefs where id=f.report_id) from public.shared_context_snapshots where id=h.context_id),'shared context binds exact reviewed draft and original report');
 perform pg_temp.check((select shared_job_ref=h.id and shared_attempt_ref=h.attempt_id and context_snapshot_ref=h.context_id and actor_id=f.actor_id from public.shared_action_events where id=h.id),'preparation action links actor, job, attempt and context');
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload)->>'state'='replayed'and(select count(*)=1 from public.marketvision_handoffs where property_id=f.property_id),'lost prepare response reuses one handoff');
 perform pg_temp.check(public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload||'{"objective":"Changed"}')->>'state'='request_conflict','same request cannot change its exact draft');
 perform pg_temp.check(public.prepare_marketvision_handoff(gen_random_uuid(),f.property_id,f.actor_id,payload)->>'state'='handoff_exists','a second identity cannot duplicate an active reviewed recommendation');
 perform pg_temp.check(public.read_marketvision_handoffs(f.other_property,f.actor_id,null,h.id)->>'state'='not_found','details cannot cross properties');
 perform pg_temp.check(public.read_marketvision_handoffs(f.property_id,f.actor_id,f.report_id,h.id)->>'sourceChanged'='false','read confirms current sources without rewriting saved intent');
 begin update public.marketvision_handoffs set draft='{}'where id=h.id;raise exception 'MISSING immutable draft';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm like 'Prepare a new handoff%','saved draft cannot be edited in place');end;
 begin update public.shared_action_attempts set proposal_decision_status='approved'where id=h.attempt_id;raise exception 'MISSING generic approval guard';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Review this handoff in MarketVision','generic approval cannot bypass exact evidence and target review');end;
 begin update public.shared_jobs set lifecycle_status='cancelled'where id=h.id;raise exception 'MISSING generic job guard';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Review this handoff in MarketVision','generic job mutation cannot bypass handoff decision');end;
 decision:=jsonb_build_object('handoffId',h.id,'expectedVersion',1,'draftHash',h.draft_hash,'decision','approve','reason','Approve the exact draft and original evidence');
 perform pg_temp.check(public.decide_marketvision_handoff(decision_id,f.other_property,f.actor_id,decision)->>'state'='not_found','approval cannot cross properties');
 select role into old_role from public.profiles where id=f.actor_id;update public.profiles set role='viewer'where id=f.actor_id;
 perform pg_temp.check(public.decide_marketvision_handoff(decision_id,f.property_id,f.actor_id,decision)->>'state'='manager_required','operator cannot approve without current manager role');update public.profiles set role=old_role where id=f.actor_id;
 perform pg_temp.check(public.decide_marketvision_handoff(decision_id,f.property_id,f.actor_id,decision||'{"draftHash":"different"}')->>'state'='stale_handoff','approval requires the displayed exact draft hash');
 perform set_config('p11.fixture.fail_approval','yes',true);
 begin perform public.decide_marketvision_handoff(decision_id,f.property_id,f.actor_id,decision);raise exception 'MISSING atomic failure';exception when others then if sqlerrm like 'MISSING%'then raise;end if;perform pg_temp.check(sqlerrm='Injected approval receipt failure','receipt failure is surfaced rather than acknowledged');end;
 perform set_config('p11.fixture.fail_approval','no',true);
 perform pg_temp.check(not exists(select 1 from public.social_content_briefs where id=h.target_id)and(select state='prepared'and version=1 from public.marketvision_handoffs where id=h.id)and not exists(select 1 from public.shared_action_events where id=h.target_id),'draft, handoff transition and action history roll back together when approval receipt fails');
 r:=public.decide_marketvision_handoff(decision_id,f.property_id,f.actor_id,decision);perform pg_temp.check(r->>'state'='saved'and(r->>'contentBriefId')::uuid=h.target_id and r->>'generationStarted'='false'and r->>'externalDelivery'='false'and r->>'businessOutcome'='unknown','approval atomically creates one draft and makes no business outcome claim');
 perform pg_temp.check((select title=h.draft->>'title'and objective=h.draft->>'objective'and source_facts=h.draft->'sourceFacts'and created_by=f.actor_id from public.social_content_briefs where id=h.target_id),'created draft equals exact reviewed intent and credits actual approver');
 perform pg_temp.check((select count(*)=1 from public.shared_approvals where action_attempt_id=h.attempt_id)and(select count(*)=1 from public.shared_policy_decisions where action_attempt_id=h.attempt_id)and(select lifecycle_status='succeeded'from public.shared_jobs where id=h.id),'approval and draft receipt finalize together');
 perform pg_temp.check((select actor_id=f.actor_id and shared_job_ref=h.id and shared_attempt_ref=h.attempt_id from public.shared_action_events where id=decision_id)and(select actor_id=f.actor_id from public.shared_action_events where id=h.target_id and action='studio.brief.saved'),'cross-product action history preserves both actual decisions');
 perform pg_temp.check(public.decide_marketvision_handoff(decision_id,f.property_id,f.actor_id,decision)->>'state'='replayed'and(select count(*)=1 from public.social_content_briefs where property_id=f.property_id),'lost approval response does not create a second draft');
 perform pg_temp.check(public.decide_marketvision_handoff(gen_random_uuid(),f.property_id,f.actor_id,decision)->>'state'='stale_handoff','different actor intent cannot decide a completed handoff again');
 -- A new recommendation review creates a distinct intent; changes after preparation block approval.
 next_id:=gen_random_uuid();perform public.review_marketvision_brief(next_id,f.property_id,f.actor_id,jsonb_build_object('briefId',f.report_id,'expectedVersion',2,'recommendationId',f.recommendation_id,'expectedReviewId',review_id,'decision','consider','acknowledgedSourceChange',false,'reason','Consider a distinct draft intent'));review_id:=next_id;
 handoff_id:=gen_random_uuid();payload:=payload||jsonb_build_object('expectedReviewId',review_id);perform public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload);select * into h from public.marketvision_handoffs where id=handoff_id;
 next_id:=gen_random_uuid();perform public.review_marketvision_brief(next_id,f.property_id,f.actor_id,jsonb_build_object('briefId',f.report_id,'expectedVersion',2,'recommendationId',f.recommendation_id,'expectedReviewId',review_id,'decision','dismiss','acknowledgedSourceChange',false,'reason','Dismiss after deeper review'));
 decision:=decision||jsonb_build_object('handoffId',h.id,'draftHash',h.draft_hash);
 perform pg_temp.check(public.decide_marketvision_handoff(gen_random_uuid(),f.property_id,f.actor_id,decision)->>'state'='stale_review','changed recommendation decision stops later approval');
 perform pg_temp.check(public.read_marketvision_handoffs(f.property_id,f.actor_id,null,h.id)->>'reviewChanged'='true','operator sees changed review before approval');
 r:=public.decide_marketvision_handoff(gen_random_uuid(),f.property_id,f.actor_id,decision||'{"decision":"reject"}');perform pg_temp.check(r->>'state'='saved'and not exists(select 1 from public.social_content_briefs where id=h.target_id),'manager can reject stale intent without creating a draft');
 review_id:=gen_random_uuid();perform public.review_marketvision_brief(review_id,f.property_id,f.actor_id,jsonb_build_object('briefId',f.report_id,'expectedVersion',2,'recommendationId',f.recommendation_id,'expectedReviewId',next_id,'decision','consider','acknowledgedSourceChange',false,'reason','Reconsider this comparison'));payload:=payload||jsonb_build_object('expectedReviewId',review_id);handoff_id:=gen_random_uuid();perform public.prepare_marketvision_handoff(handoff_id,f.property_id,f.actor_id,payload);select * into h from public.marketvision_handoffs where id=handoff_id;
 update public.competitor_units set rent_min=2222 where competitor_id=f.competitor_id;decision:=decision||jsonb_build_object('handoffId',h.id,'draftHash',h.draft_hash);
 perform pg_temp.check(public.decide_marketvision_handoff(gen_random_uuid(),f.property_id,f.actor_id,decision)->>'state'='source_changed','source change after preparation blocks draft creation');
 perform pg_temp.check(public.read_marketvision_handoffs(f.property_id,f.actor_id,null,h.id)->>'sourceChanged'='true','stale source visible in saved handoff detail');
 update public.profiles set role='viewer'where id=f.actor_id;
 r:=public.decide_marketvision_handoff(gen_random_uuid(),f.property_id,f.actor_id,decision||'{"decision":"withdraw"}');perform pg_temp.check(r->>'state'='saved','original non-manager requester can withdraw a stale handoff');update public.profiles set role=old_role where id=f.actor_id;
 perform pg_temp.check((select count(*)=1 from public.social_content_briefs where property_id=f.property_id),'rejection and withdrawal never create extra drafts');
 perform pg_temp.check(jsonb_array_length(public.read_marketvision_handoffs(f.property_id,f.actor_id,f.report_id)->'handoffs')=3,'saved history retains completed, rejected and withdrawn intents');
 perform pg_temp.check(public.read_marketvision_handoffs(f.property_id,f.actor_id,null,null,gen_random_uuid())->>'state'='cursor_changed','invalid history cursor is not a false empty state');

 -- Membership is rechecked on every read, including saved historical work.
 next_id:=gen_random_uuid();insert into public.organizations(id,name)values(next_id,'Handoff access rollback fixture');
 update public.profiles set org_id=next_id where id=f.actor_id;
 perform pg_temp.check(public.read_marketvision_handoffs(f.property_id,f.actor_id,null,h.id)->>'state'='forbidden'and public.read_marketvision_handoffs(f.property_id,f.actor_id)->>'state'='forbidden','lost organization membership cannot read saved intent or history');
 update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id=f.actor_id;

end$$;
select count(*)as passed_assertions from checks;
rollback;
